#!/usr/bin/env python3
"""
One-time bootstrap for the NC-250 reference system.

Place this file at the root of neetcode-submissions and run:

    python bootstrap_reference_system.py

Then build the references with:

    python build_references.py

Existing generated script files are preserved unless --force is supplied.
"""
from __future__ import annotations
import argparse
from pathlib import Path

FILES = {'scripts/__init__.py': '"""NC-250 reference-building package."""\n', 'scripts/reference_scanner.py': 'from __future__ import annotations\n\nimport re\nfrom dataclasses import asdict, dataclass\nfrom pathlib import Path\n\nSUBMISSION_RE = re.compile(r"^submission-(\\d+)\\.py$", re.IGNORECASE)\nTYPE_RE = re.compile(r"^\\s*TYPE\\s*:\\s*(SOLUTION_REFERENCE|INTERVIEW_REFERENCE)\\s*$", re.MULTILINE)\n\ndef slugify(value: str) -> str:\n    value = value.strip().lower().replace("&", " and ")\n    return re.sub(r"[^a-z0-9]+", "-", value).strip("-") or "unknown"\n\ndef field(text: str, name: str, default: str) -> str:\n    match = re.search(rf"^\\s*{re.escape(name)}\\s*:\\s*(.+?)\\s*$", text, re.MULTILINE)\n    return match.group(1).strip() if match else default\n\n@dataclass(frozen=True)\nclass Candidate:\n    path: Path\n    number: int\n    reference_type: str\n    category: str\n    preferred_solution: str\n    problem: str\n    difficulty: str\n\n@dataclass\nclass ProblemRecord:\n    problem_dir: Path\n    category: str\n    problem: str\n    category_slug: str\n    problem_slug: str\n    solution_reference: Candidate | None\n    interview_reference: Candidate | None\n\n    def manifest(self, repo_root: Path) -> dict:\n        def pack(candidate: Candidate | None):\n            if candidate is None:\n                return None\n            data = asdict(candidate)\n            data["path"] = candidate.path.relative_to(repo_root).as_posix()\n            return data\n        return {\n            "problem_dir": self.problem_dir.relative_to(repo_root).as_posix(),\n            "category": self.category,\n            "problem": self.problem,\n            "category_slug": self.category_slug,\n            "problem_slug": self.problem_slug,\n            "solution_reference": pack(self.solution_reference),\n            "interview_reference": pack(self.interview_reference),\n        }\n\ndef read_text(path: Path) -> str:\n    return path.read_text(encoding="utf-8-sig", errors="replace")\n\ndef candidate(path: Path) -> Candidate | None:\n    match = SUBMISSION_RE.match(path.name)\n    if not match:\n        return None\n    text = read_text(path)\n    type_match = TYPE_RE.search(text)\n    if not type_match:\n        return None\n    return Candidate(\n        path=path,\n        number=int(match.group(1)),\n        reference_type=type_match.group(1),\n        category=field(text, "CATEGORY", "Unknown"),\n        preferred_solution=field(text, "PREFERRED_SOLUTION", "Unknown"),\n        problem=field(text, "PROBLEM", path.parent.name),\n        difficulty=field(text, "DIFFICULTY", "Unknown"),\n    )\n\ndef newest(items: list[Candidate], kind: str) -> Candidate | None:\n    matches = [item for item in items if item.reference_type == kind]\n    return max(matches, key=lambda item: (item.number, item.path.stat().st_mtime_ns)) if matches else None\n\ndef scan(source_root: Path) -> list[ProblemRecord]:\n    if not source_root.is_dir():\n        raise FileNotFoundError(f"Source directory not found: {source_root}")\n\n    records: list[ProblemRecord] = []\n    for problem_dir in sorted((p for p in source_root.rglob("*") if p.is_dir()), key=lambda p: p.as_posix().lower()):\n        files = [p for p in problem_dir.iterdir() if p.is_file() and SUBMISSION_RE.match(p.name)]\n        if not files:\n            continue\n        items = [item for p in files if (item := candidate(p)) is not None]\n        solution = newest(items, "SOLUTION_REFERENCE")\n        interview = newest(items, "INTERVIEW_REFERENCE")\n        selected = interview or solution\n        category = selected.category if selected and selected.category != "Unknown" else problem_dir.parent.name\n        problem = selected.problem if selected and selected.problem != "Unknown" else problem_dir.name\n        records.append(ProblemRecord(\n            problem_dir=problem_dir,\n            category=category,\n            problem=problem,\n            category_slug=slugify(category),\n            problem_slug=slugify(problem),\n            solution_reference=solution,\n            interview_reference=interview,\n        ))\n    return records\n', 'scripts/extract_solution_references.py': 'from __future__ import annotations\nimport shutil\nfrom pathlib import Path\nfrom .reference_scanner import ProblemRecord\n\ndef extract(records: list[ProblemRecord], references_root: Path) -> list[Path]:\n    written: list[Path] = []\n    for record in records:\n        if record.solution_reference is None:\n            continue\n        destination = references_root / "solution" / record.category_slug / f"{record.problem_slug}.py"\n        destination.parent.mkdir(parents=True, exist_ok=True)\n        shutil.copyfile(record.solution_reference.path, destination)\n        written.append(destination)\n    return written\n', 'scripts/render_interview_markdown.py': 'from __future__ import annotations\nimport ast\nimport inspect\nimport re\nfrom pathlib import Path\nfrom .reference_scanner import ProblemRecord, read_text\n\nSECTIONS = {\n    "STEP_1_UNDERSTAND_THE_PROBLEM": "1. Understand the Problem",\n    "STEP_2_RESTATE_THE_PROBLEM": "2. Restate the Problem",\n    "STEP_3_CLARIFY_AND_CONFIRM": "3. Clarify and Confirm",\n    "STEP_4_IDENTIFY_INPUTS_OUTPUTS_AND_CONSTRAINTS": "4. Inputs, Outputs, and Constraints",\n    "STEP_5_BASELINE_APPROACH": "5. Baseline Approach",\n    "STEP_6_BASELINE_COMPLEXITY": "6. Baseline Complexity",\n    "STEP_7_FIND_THE_BOTTLENECK": "7. Find the Bottleneck",\n    "STEP_8_OPTIMIZATION_BRIDGE": "8. Optimization Bridge",\n    "STEP_9_PREFERRED_APPROACH": "9. Preferred Approach",\n    "STEP_10_CORRECTNESS_REASONING": "10. Correctness Reasoning",\n    "STEP_11_EXAMPLE_TRACE": "11. Example Trace",\n    "STEP_12_CODE_PLAN": "12. Code Plan",\n    "STEP_13_IMPLEMENTATION": "13. Implementation",\n    "STEP_14_TEST_CASES": "14. Test Cases",\n    "STEP_15_TIME_COMPLEXITY_DERIVATION": "15. Time Complexity Derivation",\n    "STEP_16_SPACE_COMPLEXITY_DERIVATION": "16. Space Complexity Derivation",\n    "STEP_17_APPROACH_TRADEOFFS": "17. Approach Tradeoffs",\n    "STEP_18_INTERVIEW_COMMUNICATION": "18. Interview Communication",\n    "INTERVIEW_SCRIPT": "Interview Script",\n    "PATTERN_RECOGNITION": "Pattern Recognition",\n    "COMMON_PITFALLS": "Common Pitfalls",\n    "FINAL_REVIEW_CHECKLIST": "Final Review Checklist",\n}\n\ndef reference_docstring(source: str) -> str:\n    tree = ast.parse(source)\n    for node in ast.walk(tree):\n        if isinstance(node, (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):\n            doc = ast.get_docstring(node, clean=False)\n            if doc and "TYPE: INTERVIEW_REFERENCE" in doc:\n                return inspect.cleandoc(doc)\n    raise ValueError("INTERVIEW_REFERENCE docstring not found")\n\nclass RemoveDocstrings(ast.NodeTransformer):\n    def _clean(self, node):\n        self.generic_visit(node)\n        body = getattr(node, "body", None)\n        if body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) and isinstance(body[0].value.value, str):\n            node.body = body[1:]\n        return node\n    visit_Module = _clean\n    visit_ClassDef = _clean\n    visit_FunctionDef = _clean\n    visit_AsyncFunctionDef = _clean\n\ndef executable_code(source: str) -> str:\n    tree = RemoveDocstrings().visit(ast.parse(source))\n    ast.fix_missing_locations(tree)\n    return ast.unparse(tree).strip()\n\ndef markdown_body(doc: str) -> str:\n    output: list[str] = []\n    active = False\n    content = False\n    problem_details = False\n\n    for raw in doc.splitlines():\n        line = raw.rstrip()\n        stripped = line.strip()\n        if stripped == "@NC250_START":\n            active = True\n            continue\n        if stripped == "@NC250_END":\n            break\n        if not active:\n            continue\n        if stripped == "@PROBLEM_DETAILS_START":\n            problem_details = True\n            output += ["## Problem Details", ""]\n            continue\n        if stripped == "@PROBLEM_DETAILS_END":\n            problem_details = False\n            continue\n        if stripped == "@CONTENT_START":\n            content = True\n            continue\n        if stripped == "@CONTENT_END":\n            content = False\n            continue\n        if re.match(r"^(TYPE|SCHEMA_VERSION|CATEGORY|PREFERRED_SOLUTION|PROBLEM|DIFFICULTY)\\s*:", stripped):\n            continue\n        if problem_details and stripped == "PROBLEM DETAILS:":\n            continue\n        marker = re.fullmatch(r"\\[(.+)]", stripped)\n        if marker and content:\n            key = marker.group(1)\n            output += [f"## {SECTIONS.get(key, key.replace(\'_\', \' \').title())}", ""]\n            continue\n        output.append(line)\n\n    compact: list[str] = []\n    blanks = 0\n    for line in output:\n        if line.strip():\n            blanks = 0\n            compact.append(line)\n        else:\n            blanks += 1\n            if blanks <= 2:\n                compact.append("")\n    return "\\n".join(compact).strip()\n\ndef render(records: list[ProblemRecord], references_root: Path, repo_root: Path) -> list[Path]:\n    written: list[Path] = []\n    for record in records:\n        candidate = record.interview_reference\n        if candidate is None:\n            continue\n\n        source = read_text(candidate.path)\n        destination = references_root / "interview" / record.category_slug / f"{record.problem_slug}.md"\n        destination.parent.mkdir(parents=True, exist_ok=True)\n\n        source_rel = Path(*([".."] * len(destination.parent.relative_to(repo_root).parts))) / candidate.path.relative_to(repo_root)\n        solution = references_root / "solution" / record.category_slug / f"{record.problem_slug}.py"\n        solution_line = f"- **Solution reference:** [Open](../../solution/{record.category_slug}/{record.problem_slug}.py)\\n" if solution.exists() else ""\n\n        page = (\n            f"# {record.problem}\\n\\n"\n            f"- **Category:** {record.category}\\n"\n            f"- **Difficulty:** {candidate.difficulty}\\n"\n            f"- **Preferred solution:** {candidate.preferred_solution}\\n"\n            f"- **Source submission:** [`{candidate.path.name}`]({source_rel.as_posix()})\\n"\n            f"{solution_line}"\n            f"- **Study index:** [Back to index](../../README.md)\\n\\n"\n            f"{markdown_body(reference_docstring(source))}\\n\\n"\n            "## Executable Preferred Implementation\\n\\n"\n            f"```python\\n{executable_code(source)}\\n```\\n"\n        )\n        destination.write_text(page, encoding="utf-8")\n        written.append(destination)\n    return written\n', 'scripts/build_indexes.py': 'from __future__ import annotations\nimport json\nimport os\nfrom collections import defaultdict\nfrom pathlib import Path\nfrom .reference_scanner import ProblemRecord\n\ndef rel(source_file: Path, target: Path) -> str:\n    return Path(os.path.relpath(target, source_file.parent)).as_posix()\n\ndef build(records: list[ProblemRecord], references_root: Path, repo_root: Path, combined: bool = True) -> tuple[Path, Path, Path | None]:\n    categories = defaultdict(list)\n    for record in records:\n        categories[record.category_slug].append(record)\n\n    category_root = references_root / "categories"\n    data_root = references_root / "data"\n    export_root = references_root / "exports"\n    category_root.mkdir(parents=True, exist_ok=True)\n    data_root.mkdir(parents=True, exist_ok=True)\n    export_root.mkdir(parents=True, exist_ok=True)\n\n    for slug, group in categories.items():\n        group.sort(key=lambda r: r.problem.lower())\n        page = category_root / f"{slug}.md"\n        lines = [\n            f"# {group[0].category}", "",\n            "[Back to the main study index](../README.md)", "",\n            "| Problem | Difficulty | Preferred | Solution | Interview |",\n            "|---|---|---|---|---|",\n        ]\n        for record in group:\n            chosen = record.interview_reference or record.solution_reference\n            difficulty = chosen.difficulty if chosen else "Unknown"\n            preferred = chosen.preferred_solution if chosen else "Unknown"\n            solution = references_root / "solution" / record.category_slug / f"{record.problem_slug}.py"\n            interview = references_root / "interview" / record.category_slug / f"{record.problem_slug}.md"\n            solution_link = f"[Open]({rel(page, solution)})" if solution.exists() else "Missing"\n            interview_link = f"[Study]({rel(page, interview)})" if interview.exists() else "Missing"\n            lines.append(f"| {record.problem} | {difficulty} | {preferred} | {solution_link} | {interview_link} |")\n        page.write_text("\\n".join(lines) + "\\n", encoding="utf-8")\n\n    index = references_root / "README.md"\n    complete = sum(r.solution_reference is not None and r.interview_reference is not None for r in records)\n    lines = [\n        "# NC-250 Study References", "",\n        "Generated from the newest submission of each reference type in every problem folder.", "",\n        "## Overview", "",\n        f"- Problems discovered: **{len(records)}**",\n        f"- Solution references: **{sum(r.solution_reference is not None for r in records)}**",\n        f"- Interview references: **{sum(r.interview_reference is not None for r in records)}**",\n        f"- Problems with both: **{complete}**", "",\n        "## Recommended Study Flow", "",\n        "1. Open a category.",\n        "2. Open the problem\'s **Interview** page.",\n        "3. Use **Solution** for a shorter technical review.",\n        "4. Open the source submission only when reviewing history.", "",\n        "## Categories", "",\n        "| Category | Problems | Complete | Page |",\n        "|---|---:|---:|---|",\n    ]\n    for slug, group in sorted(categories.items(), key=lambda item: item[1][0].category.lower()):\n        count = sum(r.solution_reference is not None and r.interview_reference is not None for r in group)\n        lines.append(f"| {group[0].category} | {len(group)} | {count} | [Open](categories/{slug}.md) |")\n    lines += ["", "## Missing References", "", "| Problem | Category | Missing |", "|---|---|---|"]\n    missing = 0\n    for record in sorted(records, key=lambda r: (r.category.lower(), r.problem.lower())):\n        kinds = []\n        if record.solution_reference is None:\n            kinds.append("Solution")\n        if record.interview_reference is None:\n            kinds.append("Interview")\n        if kinds:\n            missing += 1\n            lines.append(f"| {record.problem} | {record.category} | {\', \'.join(kinds)} |")\n    if not missing:\n        lines.append("| — | — | None |")\n    index.write_text("\\n".join(lines) + "\\n", encoding="utf-8")\n\n    manifest = data_root / "references.json"\n    manifest.write_text(json.dumps({\n        "schema_version": 1,\n        "problem_count": len(records),\n        "problems": [r.manifest(repo_root) for r in records],\n    }, indent=2) + "\\n", encoding="utf-8")\n\n    export = None\n    if combined:\n        export = export_root / "ALL_INTERVIEW_REFERENCES.md"\n        export_lines = [\n            "# All NC-250 Interview References", "",\n            "> Generated export. Individual problem pages are the canonical study files.", "",\n            "## Table of Contents", "",\n        ]\n        available = []\n        for record in sorted(records, key=lambda r: (r.category.lower(), r.problem.lower())):\n            page = references_root / "interview" / record.category_slug / f"{record.problem_slug}.md"\n            if page.exists():\n                anchor = f"{record.category_slug}-{record.problem_slug}"\n                export_lines.append(f"- [{record.category}: {record.problem}](#{anchor})")\n                available.append((anchor, page))\n        for anchor, page in available:\n            export_lines += ["", "---", "", f\'<a id="{anchor}"></a>\', "", page.read_text(encoding="utf-8")]\n        export.write_text("\\n".join(export_lines).rstrip() + "\\n", encoding="utf-8")\n\n    return index, manifest, export\n', 'scripts/build_references.py': 'from __future__ import annotations\nimport shutil\nfrom pathlib import Path\nfrom .build_indexes import build as build_indexes\nfrom .extract_solution_references import extract\nfrom .reference_scanner import scan\nfrom .render_interview_markdown import render\n\ndef clean(references_root: Path) -> None:\n    for name in ("solution", "interview", "categories", "data", "exports", "README.md"):\n        path = references_root / name\n        if path.is_dir():\n            shutil.rmtree(path)\n        elif path.exists():\n            path.unlink()\n\ndef build(repo_root: Path, source_root: Path, references_root: Path, clean_first: bool = False, combined: bool = True) -> dict:\n    if clean_first:\n        clean(references_root)\n    references_root.mkdir(parents=True, exist_ok=True)\n    records = scan(source_root)\n    solutions = extract(records, references_root)\n    interviews = render(records, references_root, repo_root)\n    index, manifest, export = build_indexes(records, references_root, repo_root, combined)\n    return {\n        "records": records,\n        "solutions": solutions,\n        "interviews": interviews,\n        "index": index,\n        "manifest": manifest,\n        "export": export,\n    }\n', 'build_references.py': '#!/usr/bin/env python3\nfrom __future__ import annotations\n\nimport argparse\nimport sys\nfrom pathlib import Path\nfrom scripts.build_references import build\n\ndef arguments() -> argparse.Namespace:\n    parser = argparse.ArgumentParser(description="Build NC-250 study references.")\n    parser.add_argument("--source", default="Data Structures & Algorithms")\n    parser.add_argument("--references", default="references")\n    parser.add_argument("--clean", action="store_true")\n    parser.add_argument("--no-export", action="store_true")\n    return parser.parse_args()\n\ndef main() -> int:\n    args = arguments()\n    root = Path(__file__).resolve().parent\n    try:\n        result = build(\n            repo_root=root,\n            source_root=root / args.source,\n            references_root=root / args.references,\n            clean_first=args.clean,\n            combined=not args.no_export,\n        )\n    except (OSError, ValueError, SyntaxError) as exc:\n        print(f"Build failed: {exc}", file=sys.stderr)\n        return 1\n\n    records = result["records"]\n    print("NC-250 reference build complete.")\n    print(f"  Problems discovered:       {len(records)}")\n    print(f"  Solution references built: {len(result[\'solutions\'])}")\n    print(f"  Interview pages built:     {len(result[\'interviews\'])}")\n    print(f"  Missing solution refs:     {sum(r.solution_reference is None for r in records)}")\n    print(f"  Missing interview refs:    {sum(r.interview_reference is None for r in records)}")\n    print(f"  Study index:               {result[\'index\']}")\n    print(f"  Manifest:                  {result[\'manifest\']}")\n    if result["export"]:\n        print(f"  Combined export:           {result[\'export\']}")\n    return 0\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'}

DIRECTORIES = (
    "references/solution",
    "references/interview",
    "references/categories",
    "references/data",
    "references/exports",
    "scripts",
)

def main() -> int:
    parser = argparse.ArgumentParser(description="Bootstrap the NC-250 reference system.")
    parser.add_argument("--force", action="store_true", help="Overwrite existing generated scripts.")
    args = parser.parse_args()
    root = Path(__file__).resolve().parent

    for directory in DIRECTORIES:
        (root / directory).mkdir(parents=True, exist_ok=True)

    written = skipped = 0
    for relative, content in FILES.items():
        destination = root / relative
        destination.parent.mkdir(parents=True, exist_ok=True)
        if destination.exists() and not args.force:
            skipped += 1
            print(f"Kept existing: {relative}")
            continue
        destination.write_text(content, encoding="utf-8")
        written += 1
        print(f"Created: {relative}")

    print()
    print("Bootstrap complete.")
    print(f"  Files created/replaced: {written}")
    print(f"  Existing files kept:    {skipped}")
    print("  Next: python build_references.py")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
